    ("gov_m5_36", "International Organizations: Commonwealth of Nations", "2010", "The Commonwealth of Nations is a voluntary association comprising:", ["Great Britain and countries that were formerly British colonies and dependencies", "All English-speaking countries in Europe and America", "Only monarchies in the British Isles", "All member states of the United Nations"], 0, "The Commonwealth connects 56 independent member states, mostly former territories of the British Empire, fostering educational, legal, and economic cooperation.", "Easy"),
    ("gov_m5_37", "International Organizations: Head of Commonwealth", "2010", "The ceremonial Head of the Commonwealth of Nations is the:", ["British Monarch", "Secretary-General of the United Nations", "Prime Minister of Great Britain", "President of Nigeria"], 0, "The British Monarch serves as the symbolic Head of the Commonwealth association.", "Easy"),
    ("gov_m5_38", "International Organizations: Commonwealth Secretary-General", "2011", "The Nigerian statesman who served two terms as Secretary-General of the Commonwealth of Nations from 1990 to 2000 was:", ["Chief Emeka Anyaoku", "Chief Jerome Udoji", "Prof. Bolaji Akinyemi", "Alhaji Babatunde Jose"], 0, "Chief Emeka Anyaoku led the Commonwealth Secretariat through historic transitions, including South Africa's democratization.", "Easy"),
    ("gov_m5_39", "International Organizations: OPEC Foundation", "2010", "The Organization of the Petroleum Exporting Countries (OPEC) was founded in September 1960 at the Baghdad Conference by:", ["Iran, Iraq, Kuwait, Saudi Arabia, and Venezuela", "Nigeria, Libya, Algeria, Gabon, and Angola", "United States, Britain, France, Norway, and Canada", "Russia, China, Egypt, Syria, and Qatar"], 0, "The five founding nations formed OPEC to defend petroleum export revenues against exploitation by Western multinational oil cartels.", "Easy"),
    ("gov_m5_40", "International Organizations: Nigeria in OPEC", "2010", "Nigeria joined OPEC as its eleventh member state in the year:", ["1971", "1960", "1975", "1983"], 0, "Nigeria formally joined OPEC in July 1971 under the military administration of General Yakubu Gowon.", "Easy"),
